    function blur(ctx, imageData, amount){
	var width = imageData.width;
	var width4 = width << 2;
	var height = imageData.height;
	var data = imageData.data;
	var q, qq, qqq, b0, b1, b2, b3, bigB, index, indexLast;
	var pixel, ppixel, pppixel, ppppixel;
	var c = 0;
	if( amount === undefined ){
	    amount = 30;
	}
	amount /= 10;
	if (amount < 0.0) {
	    amount = 0.0;
	}
	if (amount >= 2.5) {
	    q = 0.98711 * amount - 0.96330;
	} else if (amount >= 0.5) {
	    q = 3.97156 - 4.14554 * Math.sqrt(1.0 - 0.26891 * amount);
	} else {
	    q = 2 * amount * (3.97156 - 4.14554 * Math.sqrt(1.0 - 0.26891 * 0.5));
	}
	qq = q * q;
	qqq = qq * q;
	b0 = 1.57825 + (2.44413 * q) + (1.4281 * qq ) + (0.422205 * qqq);
	b1 = ((2.44413 * q) + (2.85619 * qq) + (1.26661 * qqq)) / b0;
	b2 = (-((1.4281 * qq) + (1.26661 * qqq))) / b0;
	b3 = (0.422205 * qqq) / b0;
	bigB = 1.0 - (b1 + b2 + b3);
	for (c = 0; c < 3; c++) {
	    for (var y = 0; y < height; y++) {
		index = y * width4 + c;
		indexLast = y * width4 + ((width - 1) << 2) + c;
		pixel = data[index];
		ppixel = pixel;
		pppixel = ppixel;
		ppppixel = pppixel;
		for (; index <= indexLast; index += 4) {
		    pixel = bigB * data[index] + b1 * ppixel + b2 * pppixel + b3 * ppppixel;
		    data[index] = pixel;
		    ppppixel = pppixel;
		    pppixel = ppixel;
		    ppixel = pixel;
		}
		index = y * width4 + ((width - 1) << 2) + c;
		indexLast = y * width4 + c;
		pixel = data[index];
		ppixel = pixel;
		pppixel = ppixel;
		ppppixel = pppixel;
		for (; index >= indexLast; index -= 4) {
		    pixel = bigB * data[index] + b1 * ppixel + b2 * pppixel + b3 * ppppixel;
		    data[index] = pixel;
		    ppppixel = pppixel;
		    pppixel = ppixel;
		    ppixel = pixel;
		}
	    }
	}
	for (c = 0; c < 3; c++) {
	    for (var x = 0; x < width; x++) {
		index = (x << 2) + c;
		indexLast = (height - 1) * width4 + (x << 2) + c;
		pixel = data[index];
		ppixel = pixel;
		pppixel = ppixel;
		ppppixel = pppixel;
		for (; index <= indexLast; index += width4) {
		    pixel = bigB * data[index] + b1 * ppixel + b2 * pppixel + b3 * ppppixel;
		    data[index] = pixel;
		    ppppixel = pppixel;
		    pppixel = ppixel;
		    ppixel = pixel;
		}
		index = (height - 1) * width4 + (x << 2) + c;
		indexLast = (x << 2) + c;
		pixel = data[index];
		ppixel = pixel;
		pppixel = ppixel;
		ppppixel = pppixel;
		for (; index >= indexLast; index -= width4) {
		    pixel = bigB * data[index] + b1 * ppixel + b2 * pppixel + b3 * ppppixel;
		    data[index] = pixel;
		    ppppixel = pppixel;
		    pppixel = ppixel;
		    ppixel = pixel;
		}
	    }
	}
    }


